```go
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"

	"github.com/avrolabs/go-avro"
)

// Define the function to read and process the struct definition
func readStructDefinition(filePath string) (*avro.StructDefinition, error) {
	fileData, err := ioutil.ReadFile(filePath)
	if err != nil {
		return nil, fmt.Errorf("failed to read file: %w", err)
	}

	var structDef avro.StructDefinition
	err = json.Unmarshal(fileData, &structDef)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal JSON: %w", err)
	}
	return &structDef, nil
}

// GenerateAvroSchema takes a struct definition and writes it to a specified filename.
func GenerateAvroSchema(structName string, filePath string) error {
	structDef, err := readStructDefinition(filePath)
	if err != nil {
		return fmt.Errorf("error reading struct definition: %v", err)
	}

	schemaStr, err := avro.MarshalAVRO(*structDef)
	if err != nil {
		return fmt.Errorf("error generating Avro schema: %v", err)
	}

	outputFile, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		return fmt.Errorf("error creating output file: %v", err)
	}
	defer outputFile.Close()

	_, err = outputFile.Write([]byte(schemaStr))
	if err != nil {
		return fmt.Errorf("error writing Avro schema: %v", err)
	}

	fmt.Printf("Generated Avro schema saved as %s.avsc\n", structName)
	return nil
}

